"""Clear the two analyzer warnings about U+2068 / U+2069.

The bidi() helper had the isolate characters written into the source as the
characters themselves rather than as escape sequences. They are invisible, so
the line read differently to a human than it compiled - the hazard the analyzer
is warning about. They are now written as \\u2068 and \\u2069, which Dart turns
into the same two characters at runtime, so behaviour is unchanged and the
source is plain ASCII.

Run it from the root of the repository:

    py fix_unicode_warning.py

Safe to run twice. App only - no backend change, no container rebuild.
"""

import base64
import pathlib
import sys

FILES = {
    'mobile/lib/i18n.dart':
        '',
}


def main() -> int:
    root = pathlib.Path.cwd()
    if not (root / "mobile" / "lib" / "main.dart").is_file():
        print("Run this from the repository root (the folder that contains 'mobile').")
        print("You are in:", root)
        return 1
    for name, blob in FILES.items():
        path = root / name
        data = base64.b64decode(blob)
        before = path.read_bytes() if path.is_file() else b""
        path.write_bytes(data)
        print(("unchanged  " if before == data else "written    ") + name)
    print()
    print("    cd mobile")
    print("    flutter analyze --no-fatal-infos")
    print("    flutter test")
    return 0


if __name__ == "__main__":
    sys.exit(main())
